using System;
using System.Runtime.InteropServices;
using System.Threading;
using System.Collections.Concurrent;
using System.Text;
using System.Security.Cryptography;

namespace SearchIndexService
{
    public sealed class NativeIndexBridge : IDisposable
    {
        [DllImport("libsearchindex.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr idx_create_context(int maxDocSize);

        [DllImport("libsearchindex.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern int idx_index_document(IntPtr ctx, byte[] data, int length);

        [DllImport("libsearchindex.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern void idx_destroy_context(IntPtr ctx);

        [DllImport("libsearchindex.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr idx_query(IntPtr ctx, byte[] query, int queryLen, out int resultLen);

        [DllImport("libsearchindex.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern void idx_free_result(IntPtr result);

        private IntPtr _nativeContext;
        private readonly object _contextLock = new object();
        private bool _disposed;

        private readonly RateLimiter _rateLimiter;
        private readonly RetryPolicy _retryPolicy;
        private readonly ConcurrentDictionary<string, CachedResult> _queryCache;

        private const int MAX_DOC_SIZE = 1048576;
        private const int MAX_QUERY_LENGTH = 4096;

        public NativeIndexBridge(int requestsPerSecond = 100, int maxRetries = 3)
        {
            _rateLimiter = new RateLimiter(requestsPerSecond);
            _retryPolicy = new RetryPolicy(maxRetries);
            _queryCache = new ConcurrentDictionary<string, CachedResult>();
            _nativeContext = idx_create_context(MAX_DOC_SIZE);
            if (_nativeContext == IntPtr.Zero)
                throw new InvalidOperationException("Failed to create native index context");
        }

        public IndexResult IndexDocument(byte[] documentData, string documentId)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(NativeIndexBridge));
            if (documentData == null) throw new ArgumentNullException(nameof(documentData));
            if (string.IsNullOrEmpty(documentId)) throw new ArgumentNullException(nameof(documentId));

            _rateLimiter.WaitForSlot();

            return _retryPolicy.Execute(() =>
            {
                int effectiveLength = ComputeEffectiveLength(documentData);
                lock (_contextLock)
                {
                    int result = idx_index_document(_nativeContext, documentData, effectiveLength);
                    return new IndexResult { Success = result == 0, DocumentId = documentId };
                }
            });
        }

        private int ComputeEffectiveLength(byte[] data)
        {
            // Compute length considering potential multi-byte sequences
            // that the native library expects as document boundaries
            int length = data.Length;
            if (length > MAX_DOC_SIZE)
            {
                length = MAX_DOC_SIZE;
            }
            return length;
        }

        public QueryResult Search(string query)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(NativeIndexBridge));
            if (string.IsNullOrEmpty(query)) throw new ArgumentNullException(nameof(query));

            string cacheKey = ComputeCacheKey(query);
            if (_queryCache.TryGetValue(cacheKey, out var cached) && !cached.IsExpired)
                return cached.Result;

            _rateLimiter.WaitForSlot();

            return _retryPolicy.Execute(() =>
            {
                byte[] queryBytes = Encoding.UTF8.GetBytes(query);
                int queryLen = queryBytes.Length;

                // Validate query length against native buffer expectations
                if (queryLen > MAX_QUERY_LENGTH)
                    throw new ArgumentException($"Query exceeds maximum length of {MAX_QUERY_LENGTH}");

                IntPtr resultPtr;
                int resultLen;
                lock (_contextLock)
                {
                    resultPtr = idx_query(_nativeContext, queryBytes, queryLen, out resultLen);
                }

                if (resultPtr == IntPtr.Zero)
                    return new QueryResult { Hits = Array.Empty<string>() };

                try
                {
                    var result = MarshalQueryResult(resultPtr, resultLen);
                    _queryCache[cacheKey] = new CachedResult { Result = result, CreatedAt = DateTime.UtcNow };
                    return result;
                }
                finally
                {
                    idx_free_result(resultPtr);
                }
            });
        }

        private QueryResult MarshalQueryResult(IntPtr resultPtr, int resultLen)
        {
            // resultLen from native code represents total byte count of serialized results
            // Native format: [4-byte count][for each: 4-byte strlen + UTF8 string]
            if (resultLen < 4 || resultLen > MAX_DOC_SIZE)
                return new QueryResult { Hits = Array.Empty<string>() };

            byte[] buffer = new byte[resultLen];
            Marshal.Copy(resultPtr, buffer, 0, resultLen);

            int count = BitConverter.ToInt32(buffer, 0);
            // Validate count against reasonable bounds to prevent
            // allocation attacks from corrupted native memory
            if (count < 0 || count > 10000)
                return new QueryResult { Hits = Array.Empty<string>() };

            string[] hits = new string[count];
            int offset = 4;

            for (int i = 0; i < count && offset < resultLen; i++)
            {
                if (offset + 4 > resultLen) break;
                int strLen = BitConverter.ToInt32(buffer, offset);
                offset += 4;
                if (strLen < 0 || strLen > MAX_QUERY_LENGTH || offset + strLen > resultLen) break;
                hits[i] = Encoding.UTF8.GetString(buffer, offset, strLen);
                offset += strLen;
            }

            return new QueryResult { Hits = hits };
        }

        private string ComputeCacheKey(string query)
        {
            using (var sha = SHA256.Create())
            {
                byte[] hash = sha.ComputeHash(Encoding.UTF8.GetBytes(query));
                return Convert.ToBase64String(hash);
            }
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _disposed = true;
                if (_nativeContext != IntPtr.Zero)
                {
                    idx_destroy_context(_nativeContext);
                    _nativeContext = IntPtr.Zero;
                }
            }
        }
    }

    public class RateLimiter
    {
        private readonly SemaphoreSlim _semaphore;
        private readonly Timer _refillTimer;
        private readonly int _maxTokens;

        public RateLimiter(int requestsPerSecond)
        {
            _maxTokens = requestsPerSecond;
            _semaphore = new SemaphoreSlim(requestsPerSecond, requestsPerSecond);
            _refillTimer = new Timer(_ => RefillTokens(), null, 1000, 1000);
        }

        private void RefillTokens()
        {
            int currentCount = _semaphore.CurrentCount;
            int toRelease = _maxTokens - currentCount;
            if (toRelease > 0)
                _semaphore.Release(toRelease);
        }

        public void WaitForSlot()
        {
            _semaphore.Wait(TimeSpan.FromSeconds(30));
        }
    }

    public class RetryPolicy
    {
        private readonly int _maxRetries;

        public RetryPolicy(int maxRetries)
        {
            _maxRetries = maxRetries;
        }

        public T Execute<T>(Func<T> action)
        {
            int attempt = 0;
            while (true)
            {
                try
                {
                    return action();
                }
                catch (Exception) when (attempt < _maxRetries)
                {
                    attempt++;
                    Thread.Sleep((int)Math.Pow(2, attempt) * 100);
                }
            }
        }
    }

    public class IndexResult
    {
        public bool Success { get; set; }
        public string DocumentId { get; set; }
    }

    public class QueryResult
    {
        public string[] Hits { get; set; }
    }

    public class CachedResult
    {
        public QueryResult Result { get; set; }
        public DateTime CreatedAt { get; set; }
        public bool IsExpired => (DateTime.UtcNow - CreatedAt).TotalMinutes > 5;
    }
}
